package com.healpay.simulator;

/** Realistic payment situations generated by the simulator. */
public enum Scenario {
    CLEAN("Everything matches"),
    FAILED_CLEAN("Failed payment, consistently failed everywhere"),
    MISSED_WEBHOOK("Gateway success webhook never reached our ledger"),
    DUPLICATE_CAPTURE("Customer charged twice after a retry"),
    FEE_GST("Gateway deducted GST on top of the contracted fee"),
    TRUNCATED_REF_STRONG("Bank dropped the UTR; narration has most of the reference"),
    TRUNCATED_REF_WEAK("Bank dropped the UTR; narration has only a fragment"),
    GATEWAY_FAILED_LEDGER_SUCCESS("Ledger booked success for a payment that failed"),
    DELAYED_SETTLEMENT("Settlement arrives a little later than capture"),
    ORPHAN_CREDIT("Unknown credit in the bank statement");

    private final String description;

    Scenario(String description) {
        this.description = description;
    }

    public String getDescription() {
        return description;
    }

    /** One of every anomaly - used for the "Generate demo incidents" button. */
    public static final Scenario[] ANOMALIES = {
            MISSED_WEBHOOK, DUPLICATE_CAPTURE, FEE_GST, TRUNCATED_REF_STRONG, TRUNCATED_REF_WEAK,
            GATEWAY_FAILED_LEDGER_SUCCESS, DELAYED_SETTLEMENT, ORPHAN_CREDIT
    };
}
